// src/lib/mlm/watch-earn/submitVideoForModeration.ts
async function submitVideoForModeration(file, metadata, onProgress) {
  const currentUser = auth.currentUser;
  if (!currentUser) {
    return {
      success: false,
      message: "Please login first"
    };
  }
  if (!file) {
    return {
      success: false,
      message: "Video file is required"
    };
  }
  if (!file.type.startsWith("video/")) {
    return {
      success: false,
      message: "Only video files are allowed"
    };
  }
  if (file.size > 100 * 1024 * 1024) {
    return {
      success: false,
      message: "Video exceeds the 100MB limit"
    };
  }
  const token = await currentUser.getIdToken(true);
  console.log("[UPLOAD_DEBUG] SUBMIT_START", {
    fileName: file.name,
    fileSize: file.size,
    fileType: file.type,
    creatorId: currentUser.uid
  });
  const startResponse = await fetch("/api/creator/start-drive-upload", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify({
      filename: file.name,
      mimeType: file.type,
      fileSize: file.size,
      ...metadata
    })
  });
  const startData = await startResponse.json();
  console.log("[UPLOAD_DEBUG] START_RESPONSE", {
    status: startResponse.status,
    ok: startResponse.ok,
    success: startData?.success,
    submissionId: startData?.submissionId,
    uploadUrlPresent: !!startData?.uploadUrl,
    message: startData?.message
  });
  if (!startResponse.ok || !startData.success || !startData.submissionId || !startData.uploadUrl) {
    return {
      success: false,
      message: startData.message || "Failed to initialize upload"
    };
  }
  const { submissionId, uploadUrl } = startData;
  console.log("[UPLOAD_DEBUG] DRIVE_UPLOAD_START", {
    submissionId,
    uploadUrlPresent: !!uploadUrl
  });
  try {
    const driveFileId = await uploadVideoToDrive(file, uploadUrl, onProgress);
    console.log("[UPLOAD_DEBUG] DRIVE_UPLOAD_RETURNED", {
      submissionId,
      driveFileId
    });
    console.log("[UPLOAD_DEBUG] COMPLETE_REQUEST_START", {
      submissionId,
      driveFileId
    });
    const completeResponse = await fetch("/api/creator/complete-drive-upload", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        submissionId,
        driveFileId
      })
    });
    const completeData = await completeResponse.json().catch(() => null);
    console.log("[UPLOAD_DEBUG] COMPLETE_RESPONSE", {
      status: completeResponse.status,
      ok: completeResponse.ok,
      data: completeData
    });
    if (!completeResponse.ok || !completeData || completeData.success !== true) {
      throw new Error(
        typeof completeData?.message === "string" ? completeData.message : "Failed to complete submission"
      );
    }
    return {
      success: true,
      submissionId,
      driveFileId
    };
  } catch (error2) {
    console.error("[UPLOAD_DEBUG] SUBMIT_ERROR", {
      name: error2 instanceof Error ? error2.name : typeof error2,
      message: error2 instanceof Error ? error2.message : String(error2),
      stack: error2 instanceof Error ? error2.stack : void 0,
      submissionId
    });
    try {
      const recoveryResponse = await fetch(
        "/api/creator/recover-drive-upload",
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json"
          },
          body: JSON.stringify({ submissionId })
        }
      );
      const recoveryData = await recoveryResponse.json().catch(() => null);
      console.log("[UPLOAD_DEBUG] RECOVERY_RESPONSE", {
        status: recoveryResponse.status,
        ok: recoveryResponse.ok,
        data: recoveryData
      });
      if (recoveryResponse.ok && recoveryData?.success === true && recoveryData?.completed === true && typeof recoveryData.driveFileId === "string" && recoveryData.driveFileId) {
        const recoveredDriveFileId = recoveryData.driveFileId;
        const recoveredCompleteResponse = await fetch(
          "/api/creator/complete-drive-upload",
          {
            method: "POST",
            headers: {
              Authorization: `Bearer ${token}`,
              "Content-Type": "application/json"
            },
            body: JSON.stringify({
              submissionId,
              driveFileId: recoveredDriveFileId
            })
          }
        );
        const recoveredCompleteData = await recoveredCompleteResponse.json().catch(() => null);
        console.log("[UPLOAD_DEBUG] RECOVERED_COMPLETE_RESPONSE", {
          status: recoveredCompleteResponse.status,
          ok: recoveredCompleteResponse.ok,
          data: recoveredCompleteData
        });
        if (recoveredCompleteResponse.ok && recoveredCompleteData?.success === true) {
          onProgress?.(file.size, file.size);
          return {
            success: true,
            submissionId,
            driveFileId: recoveredDriveFileId
          };
        }
      }
      if (recoveryResponse.ok && recoveryData?.success === true && Number(recoveryData?.uploadedBytes) > 0 && Number(recoveryData?.uploadedBytes) < file.size) {
        try {
          const resumedDriveFileId = await uploadVideoToDrive(
            file,
            uploadUrl,
            onProgress
          );
          const resumedCompleteResponse = await fetch(
            "/api/creator/complete-drive-upload",
            {
              method: "POST",
              headers: {
                Authorization: `Bearer ${token}`,
                "Content-Type": "application/json"
              },
              body: JSON.stringify({
                submissionId,
                driveFileId: resumedDriveFileId
              })
            }
          );
          const resumedCompleteData = await resumedCompleteResponse.json().catch(() => null);
          console.log("[UPLOAD_DEBUG] RESUMED_COMPLETE_RESPONSE", {
            status: resumedCompleteResponse.status,
            ok: resumedCompleteResponse.ok,
            data: resumedCompleteData
          });
          if (resumedCompleteResponse.ok && resumedCompleteData?.success === true) {
            onProgress?.(file.size, file.size);
            return {
              success: true,
              submissionId,
              driveFileId: resumedDriveFileId
            };
          }
        } catch (resumeError) {
          console.error("[UPLOAD_DEBUG] RESUME_AFTER_RECOVERY_FAILED", {
            name: resumeError instanceof Error ? resumeError.name : typeof resumeError,
            message: resumeError instanceof Error ? resumeError.message : String(resumeError),
            submissionId
          });
        }
      }
    } catch (recoveryError) {
      console.error("[UPLOAD_DEBUG] RECOVERY_REQUEST_FAILED", {
        name: recoveryError instanceof Error ? recoveryError.name : typeof recoveryError,
        message: recoveryError instanceof Error ? recoveryError.message : String(recoveryError),
        submissionId
      });
    }
    await fetch("/api/creator/cancel-video-moderation", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ submissionId })
    });
    return {
      success: false,
      message: error2 instanceof Error ? error2.message : "Video submission failed"
    };
  }
}

// src/lib/mlm/watch-earn/uploadWatchVideo.ts
async function uploadWatchVideo({
  file,
  displayName,
  photoURL,
  username,
  caption,
  hashtags,
  music,
  sponsor,
  originalVideoId,
  originalAudioId,
  isEnhanced,
  onProgress
}) {
  try {
    const currentUser = await new Promise((resolve) => {
      if (auth.currentUser) {
        resolve(auth.currentUser);
        return;
      }
      let settled = false;
      const unsubscribe = onAuthStateChanged(auth, (user) => {
        if (settled) return;
        settled = true;
        unsubscribe();
        resolve(user);
      });
      setTimeout(() => {
        if (settled) return;
        settled = true;
        unsubscribe();
        resolve(auth.currentUser);
      }, 1e4);
    });
    if (!currentUser) {
      return {
        success: false,
        message: "Please login first"
      };
    }
    const authenticatedUserId = currentUser.uid;
    if (!authenticatedUserId) {
      return {
        success: false,
        message: "User UID not found"
      };
    }
    if (!file) {
      return {
        success: false,
        message: "Video file required"
      };
    }
    if (!file.type.startsWith("video/")) {
      return {
        success: false,
        message: "Only video upload allowed"
      };
    }
    const maxSize = 100 * 1024 * 1024;
    if (file.size > maxSize) {
      return {
        success: false,
        message: "Video too large. Maximum size is 100MB"
      };
    }
    const metadata = {
      displayName,
      photoURL,
      username,
      caption,
      hashtags,
      music,
      sponsor: sponsor === true,
      originalVideoId,
      originalAudioId,
      isEnhanced: isEnhanced === true
    };
    console.log("[UPLOAD_DEBUG] WATCH_BEFORE_SUBMIT", {
      fileName: file.name,
      fileSize: file.size,
      fileType: file.type,
      creatorId: authenticatedUserId
    });
    const result = await submitVideoForModeration(
      file,
      metadata,
      onProgress
    );
    console.log("[UPLOAD_DEBUG] WATCH_AFTER_SUBMIT", result);
    if (!result.success) {
      return {
        success: false,
        message: result.message || "Video moderation submission failed"
      };
    }
    console.log(
      "VIDEO SENT TO DRIVE MODERATION:",
      result.submissionId
    );
    return {
      success: true,
      moderationPending: true,
      submissionId: result.submissionId,
      message: "Video submitted for moderation. It will be published after approval."
    };
  } catch (error2) {
    console.error("[UPLOAD_DEBUG] WATCH_ERROR", {
      name: error2 instanceof Error ? error2.name : typeof error2,
      message: error2 instanceof Error ? error2.message : String(error2),
      stack: error2 instanceof Error ? error2.stack : void 0
    });
    return {
      success: false,
      message: error2 instanceof Error ? error2.message : "Video submission failed"
    };
  }
}

